cleanup_activity.command:
$reviewTemporaryPath = 'C:\Users\monoi\AppData\Local\Temp\tmph6nkb8e2'
if (Test-Path -LiteralPath $reviewTemporaryPath) {
    $reviewResolved = (Resolve-Path -LiteralPath $reviewTemporaryPath).Path
    $reviewTempParent = [System.IO.Path]::GetTempPath().TrimEnd('\')
    if ($reviewResolved -ne $reviewTemporaryPath -or (Split-Path -Parent $reviewResolved) -ne $reviewTempParent) { throw 'Unexpected fixture cleanup target' }
    Remove-Item -LiteralPath $reviewResolved -Recurse -Force
    Write-Output 'Removed only the terminated review fixture directory.'
}
